INSERT INTO course (course_id, course_code, course_name, credits, department_id, description) VALUES
    (1, 'CSE-101', 'Programming Fundamentals', 4, 1, 'C programming, problem solving and lab work.'),
    (2, 'CSE-201', 'Data Structures', 4, 1, 'Arrays, linked lists, trees, graphs and complexity.'),
    (3, 'CSE-301', 'Database Management Systems', 4, 1, 'Relational model, SQL, normalization and transactions.'),
    (4, 'CSE-401', 'Operating Systems', 3, 1, 'Processes, scheduling, memory and file systems.'),
    (5, 'ECE-101', 'Basic Electronics', 3, 2, 'Diodes, transistors and amplifier circuits.'),
    (6, 'ECE-202', 'Digital Logic Design', 4, 2, 'Boolean algebra, combinational and sequential circuits.'),
    (7, 'ECE-303', 'Signals and Systems', 3, 2, 'Continuous and discrete signal analysis.'),
    (8, 'ECE-404', 'Communication Systems', 4, 2, 'Modulation, transmission and receivers.'),
    (9, 'ME-101', 'Engineering Mechanics', 4, 3, 'Statics, dynamics and equilibrium of bodies.'),
    (10, 'ME-202', 'Thermodynamics', 4, 3, 'Laws of thermodynamics and power cycles.'),
    (11, 'ME-303', 'Fluid Mechanics', 3, 3, 'Fluid statics, Bernoulli equation and flow measurement.'),
    (12, 'ME-401', 'Machine Design', 4, 3, 'Design of machine elements and failure theories.'),
    (13, 'EE-101', 'Electrical Circuits', 4, 4, 'Network theorems, AC and DC circuit analysis.'),
    (14, 'EE-202', 'Electrical Machines', 4, 4, 'Transformers, induction and DC machines.'),
    (15, 'EE-303', 'Power Systems', 3, 4, 'Generation, transmission and distribution basics.'),
    (16, 'EE-404', 'Control Systems', 4, 4, 'Feedback, stability and controller design.'),
    (17, 'CIV-101', 'Engineering Drawing', 3, 5, 'Orthographic projections and building plans.'),
    (18, 'CIV-202', 'Strength of Materials', 4, 5, 'Stress, strain, bending and torsion.'),
    (19, 'CIV-303', 'Surveying', 3, 5, 'Leveling, theodolite and modern surveying tools.'),
    (20, 'CIV-401', 'Structural Analysis', 4, 5, 'Analysis of beams, trusses and frames.')
