-- every insert uses explicit ids with ON CONFLICT DO NOTHING.
-- Apply after database/schema.sql:  psql -d college -f database/seed.sql
-- =============================================================================

BEGIN;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('department', 'department_id'), COALESCE((SELECT MAX(department_id) FROM department), 1));
SELECT setval(pg_get_serial_sequence('student', 'student_id'), COALESCE((SELECT MAX(student_id) FROM student), 1));
SELECT setval(pg_get_serial_sequence('faculty', 'faculty_id'), COALESCE((SELECT MAX(faculty_id) FROM faculty), 1));
SELECT setval(pg_get_serial_sequence('course', 'course_id'), COALESCE((SELECT MAX(course_id) FROM course), 1));
SELECT setval(pg_get_serial_sequence('semester', 'semester_id'), COALESCE((SELECT MAX(semester_id) FROM semester), 1));
SELECT setval(pg_get_serial_sequence('course_offering', 'offering_id'), COALESCE((SELECT MAX(offering_id) FROM course_offering), 1));
SELECT setval(pg_get_serial_sequence('faculty_assignment', 'assignment_id'), COALESCE((SELECT MAX(assignment_id) FROM faculty_assignment), 1));
SELECT setval(pg_get_serial_sequence('enrollment', 'enrollment_id'), COALESCE((SELECT MAX(enrollment_id) FROM enrollment), 1));
SELECT setval(pg_get_serial_sequence('grade', 'grade_id'), COALESCE((SELECT MAX(grade_id) FROM grade), 1));

COMMIT;
